<script setup>
import { ref,computed,watch,onBeforeUnmount } from 'vue';
import { useRoute } from 'vue-router';
import { $http } from '@/plugins/axios';
import { useAuthStore } from '@/store/modules/auth';
import SubmissionDetails from './SubmissionDetails.vue';
import './collection.css';
const route=useRoute(),auth=useAuthStore();
const waiting=computed(()=>route.path.endsWith('/waiting')),tab=ref('tasks'),accounts=ref([]),sources=ref([]),assignments=ref({}),rows=ref([]),error=ref(''),message=ref(''),busy=ref(false),detail=ref(null),reviewNote=ref(''),form=ref(null),status=ref(''),page=ref(1),last=ref(1),search=ref(''),assigned=ref({});
const user=JSON.parse(localStorage.getItem('user')||'null'),labId=ref(route.query.lab_id||'');
const isAdmin=Number(user?.role_id)===1, manage=computed(()=>[1,2].includes(Number(user?.role_id))||auth.havePermission('sample logistics manage')),review=computed(()=>[1,2].includes(Number(user?.role_id))||auth.havePermission('sample logistics review'));
const params=()=>isAdmin?{lab_id:labId.value}:{};
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad'}).format(new Date()),from=ref(today),to=ref(today);
const names={requested:'بانتظار الاستلام',collected:'تم استلام العينة',delivered:'تم توصيل العينة',cancelled:'ملغي',pending:'بانتظار المراجعة',approved:'معتمد',rejected:'مرفوض'};
let version=0;
async function load(){const v=++version;error.value='';busy.value=true;try{if(isAdmin&&!labId.value)return;const endpoint=waiting.value?'waiting':tab.value;const {data}=await $http.get('/sample-logistics/'+endpoint,{params:{...params(),status:status.value||undefined,page:page.value,search:search.value||undefined,from:from.value,to:to.value}});if(v!==version)return;if(endpoint==='accounts'){accounts.value=data.data;sources.value=data.sources;assignments.value=Object.fromEntries(data.assignments.map(a=>[a.source_lab_id,a.collector_id]));}else{rows.value=data.data;last.value=data.last_page||1;}if(endpoint==='tasks'&&manage.value){const response=await $http.get('/sample-logistics/accounts',{params:params()});if(v===version)accounts.value=response.data.data;}}catch(e){if(v===version)error.value=e.response?.data?.message||'تعذر تحميل البيانات.';}finally{if(v===version)busy.value=false;}}
async function act(callback){busy.value=true;error.value='';message.value='';try{await callback();message.value='تم الحفظ بنجاح.';await load();}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat()[0]||e.response?.data?.message||'تعذر إتمام العملية.';}finally{busy.value=false;}}
function edit(u){form.value=u?{...u,password:'',status:Boolean(u.status)}:{name:'',email:'',phone_number:'',password:'',status:true};}
async function save(){await act(async()=>{await $http[form.value.id?'put':'post']('/sample-logistics/accounts'+(form.value.id?'/'+form.value.id:''),{...form.value,...params()});form.value=null;});}
async function assign(source){await act(()=>$http.put('/sample-logistics/assignments',{...params(),source_lab_id:source.id,collector_id:assignments.value[source.id]||null}));}
async function open(row){busy.value=true;try{detail.value=(await $http.get('/sample-logistics/waiting/'+row.id,{params:params()})).data;reviewNote.value='';}catch(e){error.value=e.response?.data?.message||'تعذر فتح الفاتورة';}finally{busy.value=false;}}
async function decide(decision){await act(async()=>{const {data}=await $http.post(`/sample-logistics/waiting/${detail.value.submission.id}/review`,{...params(),decision,note:reviewNote.value});detail.value.submission={...detail.value.submission,...data};});}
watch(()=>[route.path,tab.value],()=>{status.value=waiting.value?'pending':'';page.value=1;detail.value=null;load();},{immediate:true});onBeforeUnmount(()=>version++);
</script>
<template><section class="collection-panel collection-management" dir="rtl"><header class="collection-heading"><div><small>Digital Lab · إدارة العمل الميداني</small><h1>{{waiting?'قائمة الانتظار':'إدارة سحب العينات'}}</h1><p>{{waiting?'راجع فواتير المندوبين واعتمدها لإدخال النتائج.':'الحسابات وجهات الاستلام وحركة العينات في مكان واحد.'}}</p></div><RouterLink v-if="!waiting&&review" to="/sample-logistics/waiting">قائمة الانتظار ←</RouterLink><RouterLink v-if="waiting" to="/sample-logistics">إدارة سحب العينات ←</RouterLink></header><p v-if="error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><div v-if="isAdmin" class="collection-tools"><label>رقم المختبر<input type="number" min="1" v-model="labId"></label><button @click="load">فتح المختبر</button></div><nav v-if="!waiting" class="collection-tools" aria-label="أقسام إدارة السحب"><button v-for="[key,label] in [['tasks','طلبات السحب'],['accounts','المندوبون والمختبرات'],['statistics','الإحصائيات']]" :key="key" :aria-pressed="tab===key" @click="tab=key">{{label}}</button></nav>
<template v-if="waiting||tab==='tasks'"><div class="collection-tools"><label>الحالة<select v-model="status"><option value="">جميع الحالات</option><option v-for="key in (waiting?['pending','approved','rejected']:['requested','collected','delivered','cancelled'])" :key="key" :value="key">{{names[key]}}</option></select></label><label v-if="!waiting">اسم المريض أو رقم الفاتورة<input v-model="search" @keyup.enter="page=1;load()"></label><button :disabled="busy" @click="page=1;load()">بحث وتحديث</button></div><div class="collection-grid"><article v-for="row in rows" :key="row.id" class="collection-card"><small>طلب #{{row.id}} · {{row.collector_name||'لم يُعيّن مندوب'}}</small><h2>{{waiting?row.patient_name:row.details.patient?.name}}</h2><p>{{names[row.status]}}</p><template v-if="waiting"><p>{{Number(row.total).toLocaleString('ar-IQ')}} د.ع</p><button :disabled="busy" @click="open(row)">مراجعة التفاصيل</button></template><template v-else><p>{{row.details.source?.name||'مريض مباشر'}} · {{row.details.source?.address}}</p><p v-for="(item,i) in row.details.items" :key="i">{{item.name}}<small v-if="item.children?.length">: {{item.children.map(x=>x.name).join('، ')}}</small></p><p>العينات: {{row.sample_count??'لم تُستلم بعد'}}</p><p v-if="row.collected_at">الاستلام: {{new Date(row.collected_at).toLocaleString('ar-IQ',{timeZone:'Asia/Baghdad'})}}</p><p v-if="row.delivered_at">التوصيل: {{new Date(row.delivered_at).toLocaleString('ar-IQ',{timeZone:'Asia/Baghdad'})}}</p><div v-if="manage&&row.status==='requested'" class="collection-tools"><label>إسناد الطلب<select v-model="assigned[row.id]"><option :value="undefined">اختر المندوب</option><option v-for="a in accounts.filter(a=>a.status)" :key="a.id" :value="a.id">{{a.name}}</option></select></label><button :disabled="busy||!assigned[row.id]" @click="act(()=>$http.post('/sample-logistics/tasks/'+row.id+'/assign',{...params(),collector_id:assigned[row.id],version:row.version}))">إسناد</button></div></template></article></div><p v-if="!rows.length&&!busy" class="collection-card">لا توجد طلبات ضمن هذه الاختيارات.</p><div v-if="last>1" class="collection-tools"><button :disabled="busy||page===1" @click="page--;load()">السابق</button><span>{{page}} / {{last}}</span><button :disabled="busy||page===last" @click="page++;load()">التالي</button></div></template>
<template v-else-if="tab==='accounts'"><div class="collection-tools"><button v-if="manage" @click="edit()">إنشاء حساب مندوب</button><a href="/collector-portal/login" target="_blank" rel="noopener">رابط دخول المندوب ↗</a></div><form v-if="form" class="collection-card" @submit.prevent="save"><h2>{{form.id?'تعديل حساب المندوب':'حساب مندوب جديد'}}</h2><div class="collection-grid"><label>الاسم الكامل<input required maxlength="255" v-model="form.name"></label><label>البريد الإلكتروني<input required type="email" v-model="form.email" autocomplete="off"></label><label>رقم الهاتف<input v-model="form.phone_number" maxlength="50" dir="ltr"></label><label>{{form.id?'كلمة مرور جديدة (اختياري)':'كلمة المرور'}}<input type="password" v-model="form.password" :required="!form.id" minlength="10" autocomplete="new-password"></label></div><label class="my-3">حالة الحساب<select v-model="form.status"><option :value="true">فعال</option><option :value="false">معطل</option></select></label><div class="collection-tools"><button :disabled="busy" type="submit">حفظ الحساب</button><button type="button" @click="form=null">إلغاء</button></div></form><div class="collection-grid"><article v-for="a in accounts" :key="a.id" class="collection-card"><h2>{{a.name}}</h2><p>{{a.email}}</p><p>{{a.status?'حساب فعال':'حساب معطل'}}</p><button v-if="manage" @click="edit(a)">تعديل الحساب</button></article></div><div class="collection-card"><h2>ربط مختبرات لاب تو لاب بالمندوبين</h2><p>اختيار المندوب يطبّق على الطلبات الجديدة وغير المسندة. يمكن إعادة إسناد الطلبات السابقة من قسم طلبات السحب قبل استلامها.</p><p v-if="!sources.length">أضف مختبرات لاب تو لاب من صفحة الإحالات أولاً.</p><div v-for="source in sources" :key="source.id" class="collection-tools"><label>{{source.name}}<select v-model="assignments[source.id]" :disabled="!manage"><option :value="null">بدون مندوب</option><option v-for="a in accounts.filter(a=>a.status)" :key="a.id" :value="a.id">{{a.name}}</option></select></label><button v-if="manage" :disabled="busy" @click="assign(source)">حفظ الربط</button></div></div></template>
<template v-else><div class="collection-tools"><label>من<input type="date" v-model="from"></label><label>إلى<input type="date" v-model="to"></label><button :disabled="busy" @click="load">عرض الإحصائيات</button></div><p>حسب وقت الاستلام والتوصيل بتوقيت بغداد. «الحالية» تشمل جميع الطلبات المسندة غير المكتملة.</p><div class="collection-table"><table><thead><tr><th>المندوب</th><th>طلبات مستلمة</th><th>عينات مستلمة</th><th>طلبات موصلة</th><th>عينات موصلة</th><th>الحالية</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.name}}</td><td>{{r.collected_requests}}</td><td>{{r.collected_samples}}</td><td>{{r.delivered_requests}}</td><td>{{r.delivered_samples}}</td><td>{{r.pending}}</td></tr></tbody></table></div></template>
<div v-if="detail" class="collection-overlay" @click.self="detail=null"><section role="dialog" aria-modal="true" aria-label="مراجعة فاتورة المندوب" class="collection-dialog"><button class="mb-4" @click="detail=null">إغلاق المراجعة</button><p v-if="error" role="alert">{{error}}</p><SubmissionDetails :detail="detail"/><div v-if="detail.submission.status==='pending'" class="collection-review"><label>ملاحظة المراجعة / سبب الرفض<textarea v-model="reviewNote" maxlength="2000" rows="3"></textarea></label><div class="collection-tools"><button :disabled="busy||!auth.havePermission('invoices create')" @click="decide('approved')">اعتماد وإرسال لإدخال النتائج</button><button class="danger" :disabled="busy||!reviewNote.trim()" @click="decide('rejected')">رفض الطلب</button></div><p v-if="!auth.havePermission('invoices create')">اعتماد الفاتورة يحتاج صلاحية إنشاء الفواتير.</p></div><div v-else class="collection-review"><p>{{names[detail.submission.status]}}</p><RouterLink v-if="detail.submission.invoice_id" :to="'/medical_reports/update-result/'+detail.submission.invoice_id">فتح الفاتورة لإدخال النتائج ←</RouterLink></div></section></div></section></template>
